Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchTabs(selectedIndex = tab, onSelectedIndexChange = { tab = it }) {
        // `tab` is also the state here, so the scope's function is called on `this`.
        this.tab({{tabs.0}})
        this.tab({{tabs.1}})
    }
    if (tab == 0) {
        Column(
            modifier = Modifier.fillMaxWidth().border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.md).padding(MonarchTheme.spacing.space3),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1),
        ) {
            MonarchText(text = {{addField}}, style = MonarchTextStyle.BodyStrong)
            groups.forEach { (group, entries) ->
                MonarchText(text = group, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                entries.chunked(3).forEach { row ->
                    Row(modifier = Modifier.fillMaxWidth()) {
                        row.forEach { type ->
                            val label = typeLabels.getValue(type)
                            Row(
                                modifier = Modifier
                                    .weight(1f)
                                    .heightIn(min = 48.dp)
                                    .clickable {
                                        added++
                                        fields += MonarchFormFieldDefinition("field$added", type, label)
                                    }
                                    .padding(horizontal = MonarchTheme.spacing.space1),
                                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1),
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                MonarchIcon(SampleIcons.Plus, contentDescription = null, size = MonarchIconSize.Sm)
                                MonarchText(text = label, style = MonarchTextStyle.Caption)
                            }
                        }
                        repeat(3 - row.size) { Spacer(Modifier.weight(1f)) }
                    }
                }
            }
        }
        MonarchReorderableList(
            items = fields,
            key = { it.id },
            itemLabel = { it.label },
            onReorder = { from, to -> fields.add(to, fields.removeAt(from)) },
            modifier = Modifier.heightIn(max = MonarchTheme.spacing.space24 * 8),
        ) { field, _ ->
            Column(
                modifier = Modifier.weight(1f).clickable { editing = field.id },
            ) {
                MonarchText(text = field.label, style = MonarchTextStyle.BodyStrong)
                Row(
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = typeLabels.getValue(field.type), style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                    if (field.required) MonarchBadge(text = {{labels.required}}, size = MonarchBadgeSize.Sm)
                    if (field.conditions.isNotEmpty()) MonarchBadge(text = {{labels.conditional}}, tone = MonarchTone.Info, size = MonarchBadgeSize.Sm)
                }
            }
            MonarchIconButton(label = "Duplicate", onClick = { added++; fields.add(fields.indexOf(field) + 1, field.edited(id = "field$added")) }, size = MonarchButtonSize.Sm) {
                MonarchIcon(SampleIcons.Copy, contentDescription = null)
            }
            MonarchIconButton(label = "Remove", onClick = { fields.remove(field); if (editing == field.id) editing = null }, size = MonarchButtonSize.Sm) {
                MonarchIcon(SampleIcons.Close, contentDescription = null)
            }
        }
        val index = fields.indexOfFirst { it.id == editing }
        if (index >= 0) {
            val field = fields[index]
            Column(
                modifier = Modifier.fillMaxWidth().border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.md).padding(MonarchTheme.spacing.space3),
                verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
            ) {
                MonarchText(text = {{settings.title}}, style = MonarchTextStyle.BodyStrong)
                MonarchTextField(
                    value = field.label,
                    onValueChange = { fields[index] = field.edited(label = it) },
                    label = {{settings.question}},
                    required = true,
                    errorText = if (field.label.isBlank()) "Write the question." else null,
                )
                MonarchTextField(
                    value = field.description.orEmpty(),
                    onValueChange = { fields[index] = field.edited(description = it.ifBlank { null }) },
                    label = {{settings.help}},
                    singleLine = false,
                    minLines = 3,
                )
                MonarchDivider(variant = MonarchDividerVariant.Subtle)
                MonarchText(text = "Show this field when", style = MonarchTextStyle.Label)
                MonarchText(text = "Always shown when there are no conditions. Conditions can use earlier fields only.", style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                if (field.conditions.isEmpty()) {
                    MonarchText(text = "No conditions. This applies every time.", style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                }
                MonarchButton(
                    text = "Add condition",
                    onClick = {},
                    variant = MonarchButtonVariant.Secondary,
                    size = MonarchButtonSize.Sm,
                    leadingIcon = { MonarchIcon(SampleIcons.Plus, contentDescription = null) },
                )
            }
        }
    } else {
        fields.filter { it.isVisible(answers) }.forEach { field ->
            MonarchFieldRenderer(field = field, value = answers[field.id], onValueChange = { answers[field.id] = it })
        }
    }
}

